To find the largest geometric number, we can iterate from 999 downwards and check for the geometric condition. Similarly, to find the smallest geometric number, we can iterate from 100 upwards and check for the geometric condition. We then compute the difference between the largest and smallest geometric numbers.

Let's implement this in Python.
```python
def is_geometric(a, b, c):
    """Check if the digits a, b, c form a geometric sequence."""
    return b * b == a * c

def find_geometric_numbers():
    largest_geometric = 0
    smallest_geometric = 999

    # Check for the largest geometric number
    for a in range(9, 0, -1):
        for b in range(9, -1, -1):
            for c in range(9, -1, -1):
                if is_geometric(a, b, c) and a != b and b != c and a != c:
                    largest_geometric = 100 * a + 10 * b + c
                    break
            if largest_geometric > 0:
                break
        if largest_geometric > 0:
            break

    # Check for the smallest geometric number
    for a in range(1, 10):
        for b in range(0, 10):
            for c in range(0, 10):
                if is_geometric(a, b, c) and a != b and b != c and a != c:
                    smallest_geometric = 100 * a + 10 * b + c
                    break
            if smallest_geometric < 99:
                break
        if smallest_geometric < 99:
            break

    return largest_geometric, smallest_geometric

largest_geometric, smallest_geometric = find_geometric_numbers()
difference = largest_geometric - smallest_geometric
print((largest_geometric, smallest_geometric, difference))
```
